commands.command:
/bin/zsh -lc "mkdir -p docs/reports/process-saturation-20260828/raw && {
  printf 'timestamp=%s\\n' \""'$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  printf '"'host=%s\\n' \""'$(hostname)"
  printf '"'cwd=%s\\n' \""'$PWD"
  printf '"'branch=%s\\n' \""'$(git branch --show-current)"
  printf '"'head=%s\\n' \""'$(git rev-parse HEAD)"
  printf '"'task_input_readme_present='; test -f task-input/v1/README.md && echo yes || echo no
  printf 'task_input_manifest_present='; test -f task-input/v1/manifest.json && echo yes || echo no
} > docs/reports/process-saturation-20260828/raw/00-environment.txt
ps -axo pid,ppid,pgid,sid,uid,user,stat,etime,command -ww > docs/reports/process-saturation-20260828/raw/01-ps-before-full.txt
{
  printf 'timestamp=%s\\n' \""'$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  printf '"'total_processes='; ps -axo pid= | wc -l | tr -d ' '
  printf '\\nusers='; ps -axo user= | awk 'NF{u["'$1]++} END{print length(u)}'"'
  printf '\\nprocesses_by_user\\n'; ps -axo user= | awk 'NF{u["'$1]++} END{for (k in u) print u[k], k}'"' | sort -nr
  printf '\\nprocesses_by_command_top80\\n'; ps -axo comm= | awk 'NF{c["'$1]++} END{for (k in c) print c[k], k}'"' | sort -nr | sed -n '1,80p'
} > docs/reports/process-saturation-20260828/raw/02-counts-before.txt
{
  printf 'timestamp=%s\\n' \""'$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  ps -axo pid=,ppid=,user=,stat=,etime=,command= -ww | awk '"'{cmd="'$0; pid=$1; ppid=$2; user=$3; stat=$4; etime=$5; sub(/''^[[:space:]]*[0-9]+[[:space:]]+[0-9]+[[:space:]]+[''^[:space:]]+[[:space:]]+[''^[:space:]]+[[:space:]]+[''^[:space:]]+[[:space:]]*/, "", cmd); key=ppid "'"\\t\" user \"\\t\" cmd; counts[key]++; pids[key]=pids[key] \" \" pid} END{for (k in counts) print counts[k] \"\\t\" k \"\\tPIDS:\" pids[k]}' | sort -nr | sed -n '1,200p'
} > docs/reports/process-saturation-20260828/raw/03-children-by-ppid-command-before.txt
{
  printf 'timestamp=%s\\n' \""'$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  pstree -w 2>&1 || true
} > docs/reports/process-saturation-20260828/raw/04-pstree-before.txt'
